---@class MournBossDialog
local MournBossDialog = Class("MournBossDialog")
---@type CardComponent
local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
---@type ActivityMournUtils
local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')

--region lifecycle
function MournBossDialog:__init()
	self.events = {}
	self.data = nil
	self.activityData = nil
end

function MournBossDialog:__delete()
	self.controller = nil
	self.data = nil
	self.activityData = nil
end

function MournBossDialog:Awake()
	self.activityData = ActivityMournUtils.GetActivityData()
	--self:InitHandler()
	self:AddUIClick()
end

function MournBossDialog:AddUIClick()
	SetButtonAction(self.Btncheck, Bind(self, self.OnBtnBossDetailClickHandler))
	SetButtonAction(self.BtnList, Bind(self, self.OnBtnListClickHandler))
	CfUtils.SetActive(self.BtnReward, false)
	SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnFightHandler))
	SetButtonAction(self.BtnReward, Bind(self, self.OnBtnRewardHandler))
	SetButtonAction(self.BtnBuff,Bind(self,self.OnBtnBuffClick))
