	self._playerRankScr = CfUtils.GetLuaScr(self.WorldBossPlayerRankingsDialog, "Game.Activity.Mourn.MournBossRankNode")
end

function MournBossDialog:OnInitialize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		self:InitData()
	end))
	return coWait
end

function MournBossDialog:OnFinalize()
	for k, v in pairs(self.events) do
		Events.RemoveListener(k, v)
	end
	if self.bossHandler then
		Events.RemoveListener("BOSS_DMG_REWARD", self.bossHandler)
	end
	self.bossHandler = nil
	self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
	self:Delete()
	self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function MournBossDialog:InitHandler()
	self.bossHandler = Events.AddListener("BOSS_DMG_REWARD", function(rewardId)
		if self.data then
			if checkNumber(rewardId) == 0 then
				-- 1. 获取所有奖励
				local allRewards = CfUtils.GetCf(AutoIds.IdSetting6499, "JapaneseStoryBossDamageRewardsVo", true)
				-- 2. 获取所有可领取但未领取的奖励
				local allCanDrawButNotInListRewards = {}
				local historyMaxHurt = checkNumber(self.data.playerRank.damage)
				for i, reward in ipairs(allRewards) do
					---@type MidFestivalBossDamageRewardVo
					local rewardVo = reward
					if checkNumber(historyMaxHurt) >= checkNumber(rewardVo.upperLimit) and (not table.isContain(self.data.receivedDamageRewardIds, rewardVo.id, function(id, cId) return checkNumber(id) == checkNumber(cId)  end)) then
						table.insert(allCanDrawButNotInListRewards, rewardVo)
					end
				end
				-- 3. 将他们全部设置为已领取
				for _, rewardVo in ipairs(allCanDrawButNotInListRewards) do
					table.insert(self.data.receivedDamageRewardIds,rewardVo.id)
				end
			else
				if not not table.isContain(self.data.receivedDamageRewardIds, rewardId, function(id, cId) return checkNumber(id) == checkNumber(cId)  end) then
					table.insert(self.data.receivedDamageRewardIds, rewardId)
				end
			end
			---如果有小红点的逻辑
			self:IsHaveDMGRewards()
		end
	end)
end

function MournBossDialog:InitData()
	local success = false
	GameUtils.Request(Interfaces.ActivityTowerChangeTowerBossRank, { activityUuid = self.activityData.id }, function(request, response)
		success = true
		if checkInt(response.errCode) == 0 then
			local responseData = response.data
			self.data = responseData
			--self.data.playerRank.damage = 100000
			self:RefreshUI()
			self:IsHaveDMGRewards()
		end
	end)
	
	while not success do
		coroutine.yield()
	end
end
--endregion init

--region handler
