	UIModule.OpenDialog({
		id = Constants.UITypeIds.MournBossRankRewardDialog    --ActivityJapaneseStoryBossRankRewardsDialog
	})
end

function MournBossDialog:OnBtnBuffClick()
	UIModule.OpenDialog({id = Constants.UITypeIds.MournBuffDisplayDialog, parameters = {activityId = self.activityData.activityContentId}},  {
		{id = Constants.UITypeIds.MournBossDialog}
	})
end

function MournBossDialog:OnBtnFightHandler()
	---@type JapaneseStoryBossPlanVo
	local scheduleVo = ActivityMournUtils.GetSchConfig()
	CfUtils.DialogOpen(Constants.UITypeIds.UIFightTeamChoose, { activityUuid = self.activityData.id,
																levelId = scheduleVo.bossId, upBuffData = self:GetUpBuffData(), upGroup = ActivityMournUtils.GetUpGroup()},
			{ { id = Constants.UITypeIds.MournBossDialog } })
end

function MournBossDialog:GetUpBuffData()
	local data = {}
	local tempData = ActivityMournUtils.GetUpGroup()
	for i, v in ipairs(tempData) do
		local hasCard = cardComp:IsHasCard(v.refId)
		local tempData = {}
		tempData.refId = v.refId
		tempData.type = v.type
		local index = 1
		if hasCard then
			local cardDojo = cardComp:GetCardByConfId(v.refId)
			local star = cardDojo.star
			index = star + 1
		
		end
		tempData.commonAddId = v.additions[index].commonAddId
		table.insert(data,tempData)
	end
	return data
end

function MournBossDialog:OnBtnRewardHandler()

end

function MournBossDialog:OnBtnBossDetailClickHandler()
	---@type JapaneseStoryBossPlanVo
	local scheduleVo = ActivityMournUtils.GetSchConfig() --CfUtils.GetCfVo(AutoIds.IdSetting6500, "JapaneseStoryBossPlanVo", activityContentId)
	---@type ActivityCakeBossLevelVo
	local questVo = CfUtils.GetCfVo(AutoIds.IdSetting6608, "NightCatBossVo", scheduleVo.bossId)
	CfUtils.DialogOpen(Constants.UITypeIds.CommonBossDetailsDialog, { planVo = scheduleVo, questVo = questVo }, { { id = Constants.UITypeIds.MournBossDialog } })
end
--endregion handler

--region private
function MournBossDialog:RefreshPlayerRank()
	local activityContentId = checkNumber(self.activityData.activityContentId) ---排期表中的活动当id来用
	self.data.rank = self.data.rankInfo
	self._playerRankScr:Refresh(self.data, activityContentId)
end

function MournBossDialog:IsHaveDMGRewards()
	--是否存在未领取的逻辑
	-- 1. 获取所有奖励
	local allRewards = CfUtils.GetCf(AutoIds.IdSetting6499, "JapaneseStoryBossDamageRewardsVo", true)
	-- 2. 获取所有可领取但未领取的奖励
	local allCanDrawButNotInListRewards = {}
	local historyMaxHurt = checkNumber(self.data.playerRank.damage)
	for i, reward in ipairs(allRewards) do
		---@type MidFestivalBossDamageRewardVo
		local rewardVo = reward
		if checkNumber(historyMaxHurt) >= checkNumber(rewardVo.upperLimit) and (not table.isContain(self.data.receivedDamageRewardIds, rewardVo.id, function(id, cId) return checkNumber(id) == checkNumber(cId)  end)) then
			table.insert(allCanDrawButNotInListRewards, rewardVo)
		end
	end
end

function MournBossDialog:RefreshUI()
	local scheduleVo = ActivityMournUtils.GetSchConfig()   --CfUtils.GetCfVo(AutoIds.IdSetting6500, "JapaneseStoryBossPlanVo", activityContentId)
	local path = CS.ParseUtils.ParsePathNameByData(scheduleVo.entranceImage)
	CfUtils.FillImage(self.Bg, path)
	
	self.lineUpInfo = QuestConfMgr:GetInstance():GetAllQuestLineupVo(scheduleVo.bossId)
	for _, line in ipairs(self.lineUpInfo) do
		local ids = line.wave1NpcId
		for index, id in ipairs(ids) do
			local vo = CardConfMgr:GetInstance():GetMonsterTypeVoById(id)
			if checkNumber(vo.monsterClass) == Constants.RoleClass.Boss or checkNumber(vo.monsterClass) == Constants.RoleClass.Elite then
				local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(vo.skinId)
				CfUtils.FillText(self.TxtName, skinVo.name)
			end
		end
	end
	
	CfUtils.RefreshTopGoods({})
	
	self:RefreshPlayerRank()
	local upGroup = ActivityMournUtils.GetUpGroup()
	UICommonUtils.RefreshCommonUpGroup(self.CommRoleBonusLayoutGroup, upGroup, false,{{id = Constants.UITypeIds.MournBossDialog}})
end
--endregion private
return MournBossDialog